document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll(".menu_Links ul li").forEach(e=>{e.closest(".employee-add-page, .employee-edit-page")||e.addEventListener("click",e=>{document.querySelectorAll(".menu_Links ul li.active").forEach(e=>{e.classList.remove("active")}),e.target.classList.add("active"),document.querySelectorAll(".sections > section").forEach(t=>{e.target.textContent===t.dataset.section&&(document.querySelectorAll(".sections .visible").forEach(e=>{e.classList.remove("visible")}),t.classList.add("visible"))})})})});